import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"Camera Artist: A Multi-Agent Framework for Cinematic Language Storytelling Video Generation","description":"","frontmatter":{"title":"Camera Artist: A Multi-Agent Framework for Cinematic Language Storytelling Video Generation","arxiv":"2604.09195","date":"2026-04-10","authors":"Haobo Hu, Qi Mao, Yuanhang Li, Libiao Jin","categories":"cs.AI","topics":"智能体视频生成, 镜头语言, 多智能体协作","outline":[2,2]},"headers":[],"relativePath":"papers/2604.09195.md","filePath":"papers/2604.09195.md","lastUpdated":null}'),e={name:"papers/2604.09195.md"};function l(i,s,m,r,c,h){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="camera-artist-a-multi-agent-framework-for-cinematic-language-storytelling-video-generation" tabindex="-1">Camera Artist: A Multi-Agent Framework for Cinematic Language Storytelling Video Generation <a class="header-anchor" href="#camera-artist-a-multi-agent-framework-for-cinematic-language-storytelling-video-generation" aria-label="Permalink to &quot;Camera Artist: A Multi-Agent Framework for Cinematic Language Storytelling Video Generation&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2604.09195" target="_blank" rel="noreferrer">2604.09195</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-04-10（本文依据 html v1 全文与补充材料撰写）</td></tr><tr><td><strong>作者</strong></td><td>Haobo Hu, Qi Mao, Yuanhang Li, Libiao Jin（中国传媒大学 + 北京大学）</td></tr><tr><td><strong>分类</strong></td><td>cs.AI</td></tr><tr><td><strong>一句话</strong></td><td>在已有的多智能体电影生成流水线里加一个专职的 Cinematography Shot Agent，用递归分镜生成保证镜头间叙事连贯、用一个在 ShotBench 上 LoRA 微调的小模型把普通镜头描述改写成带专业镜头语言的描述。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/agentic">智能体视频生成</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>现有的 T2V / I2V 模型是 clip-centric 的：给一句 prompt 出一段几秒的高保真片段，局部画质优先于跨段落的电影化推理。把这些片段拼起来并不会自动变成电影。</p><p>论文指出两条具体的断裂。第一是<strong>叙事漂移</strong>：现有系统直接从场景或剧本生成镜头描述，几乎不以前一个镜头为条件，于是相邻镜头之间缺少视觉过渡逻辑，主角会突然换人、森林会突然变成湖边、夜景会突然变成白天。第二是<strong>镜头语言缺席</strong>：通用 LLM 扮演编剧时倾向于写&quot;某某感受到魔法能量&quot;这种只描述内容的 prompt，不会写&quot;高机位大远景配缓慢拉远&quot;，于是生成出来的视频画面清晰但视听语言平庸。</p><p>这两条决定了当前多智能体电影系统的天花板：能讲完一个故事，但不像一部片子。把&quot;运镜、景别、构图、布光&quot;提升为流水线里被显式规划的一等公民，是本文的目标。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>VideoGen-of-Thought (VGoT)</strong> 用逐步生成的方式做多镜头视频，人工干预很少。它在跨镜头的文本连续性上表现尚可，但生成的视频存在场景不一致（论文举例：从森林突兀切到湖边），且倾向于产出接近静止的画面。</p><p><strong>Anim-Director</strong> 用大型多模态模型驱动可控动画生成。论文的定性分析指出它会在相邻镜头间突然切换主角（Anna → Elsa），并且镜头多为静态构图，缺少显式的镜头设计。</p><p><strong>MovieAgent</strong> 用多智能体 CoT 规划自动生成电影，也是本文评测协议（VBench 指标选择、MoviePrompts 数据）的直接来源。它能保持角色身份，但叙事会突兀跳跃（从等无线电消息直接跳到追卡车），镜头大多静止。</p><p>论文对这批工作的共同批评是：MAS 框架把注意力放在&quot;剧本与画面的逻辑对齐&quot;上，结果是场景的机械拼装，缺少一部片子应有的<strong>作者性</strong>。作者明确写道，本文不重新思考 agentic 范式，而是在既有多智能体电影流水线之上补两个具体缺口。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>先看失败案例：把同一个故事给三个现有系统，叙事一致性指标不差，但人看完都觉得不像电影。这说明&quot;一致性&quot;和&quot;电影感&quot;是两个正交的维度，而现有指标只覆盖前者。</p><p>顺着&quot;哪里丢了电影感&quot;往回追，会落到镜头描述这一层。镜头描述是唯一同时决定&quot;拍什么&quot;和&quot;怎么拍&quot;的中间表示，而它现在由一个通用 LLM 一次性从场景生成。这个生成过程有两个结构性缺陷：它不看前一个镜头（所以断裂），它也不懂景别/机位/运镜的专业词汇（所以平庸）。</p><p>针对第一个缺陷，最直接的修法是模仿人类写分镜的过程——一个镜头一个镜头往下写，每写一个都要看着上一个。这就是递归。针对第二个缺陷，让通用 LLM 凭 prompt 学会镜头语言并不可靠，而<strong>现成的镜头级标注数据是存在的</strong>：ShotBench 提供了原始视频片段加上景别、角度、构图、运镜、布光的标注。有了配对数据，就可以训练一个专门做&quot;普通描述 → 电影化描述&quot;的翻译器。这两条合起来构成了 Cinematography Shot Agent。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>镜头描述是整条流水线的信息瓶颈：视频模型只能拍出描述里写了的东西。既然描述由 LLM 写，那么叙事断裂和镜头平庸都不是视频模型的问题，而是这一层写得不够好。递归让每个镜头能看见上一个镜头，解决断裂；一个在专业镜头标注上微调过的小模型负责把&quot;她感受到能量&quot;改写成&quot;高机位大远景，缓慢拉远&quot;，解决平庸。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>系统由三个 agent 构成，跑两个阶段，中间产物是一个三层分镜表示 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal">A</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">s</span><span class="mclose">}</span></span></span></span>。</p><p><strong>阶段一：footage construction。</strong> Director Agent 作为全局规划者，用结构化 CoT prompt 把用户给的故事大纲 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">O</span></span></span></span> 扩写成剧本级资源 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span></span></span></span>（细化题材、角色身份、故事线，且严格遵守原大纲），再分解成有序场景序列 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.0822em;">P</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.138em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.888em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mopen mtight">(</span><span class="mord mtight">1</span><span class="mclose mtight">)</span></span></span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.888em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mopen mtight">(</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span><span class="mclose mtight">)</span></span></span></span></span></span></span></span></span><span class="mclose">}</span></span></span></span>，每个场景含地点、情节、人物。基于角色档案与场景布局，它调用 T2I 模型生成视觉参考图 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span></span></span></span>。</p><p><strong>阶段二：shot generation。</strong> Cinematography Shot Agent 对每个场景 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.888em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.888em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mopen mtight">(</span><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span><span class="mclose mtight">)</span></span></span></span></span></span></span></span></span></span></span></span> 递归产出镜头描述序列，每条描述显式编码动作内容、相机配置、视觉构图；随后注入镜头语言细化。Video Generation Agent 从 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal">A</span></span></span></span> 取回角色级与场景级参考 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span></span></span></span>，把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span></span></span></span> 和镜头描述一起喂给多参考 I2V 模型生成片段 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.2194em;vertical-align:-0.3948em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8247em;"><span style="top:-2.4413em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3948em;"><span></span></span></span></span></span></span></span></span></span>，最后按时序拼接成长片。</p><p><strong>一个具体例子</strong>：输入事件是&quot;Elsa 感受到魔法能量&quot;。Anim-Director 输出几个视觉上雷同的镜头，VGoT 给一个固定中远景，MovieAgent 给一个基本静止的特写；Camera Artist 采用&quot;高机位大远景 + 平滑拉远&quot;，把空间感展开。再看跨镜头的例子&quot;Elsa 和 Anna 一行人进入森林并发现古老器物&quot;：基线要么突然换主角，要么把森林换成湖边、把夜景换成白天；Camera Artist 因为第二个镜头以第一个镜头为条件，能连贯地表现&quot;进入森林 → 深入探索&quot;。</p><p><strong>关键实现参数</strong>：所有 agent 的默认 LLM backbone 是 Qwen3-30B-A3B-Instruct；CLI 模块用 LoRA 微调 Qwen3-4B，数据是从 ShotBench 整理的 <strong>580 对</strong> <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>，rank 8、scaling factor 32、lr <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">4</span></span></span></span></span></span></span></span></span></span></span></span>、20 epochs、作用于所有线性层；视频生成器用 <strong>MAGREF</strong>（多参考可控性好），参考图用 <strong>Flux</strong> 生成；输出 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">832</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">480</span></span></span></span>、15 fps；全部实验跑在一张 NVIDIA Tesla A800 80G 上。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p><strong>递归分镜生成（RSG）</strong> 的形式化很简洁。镜头被分成三类：Scene Start Point <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.2089em;vertical-align:-0.3948em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-2.4413em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3948em;"><span></span></span></span></span></span></span></span></span></span>（当前场景的第一个镜头，不以任何前序镜头为输入，是递归的起点）、Scene Midpoint <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.2194em;vertical-align:-0.3948em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8247em;"><span style="top:-2.4413em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3948em;"><span></span></span></span></span></span></span></span></span></span>（需要前一个镜头内容作条件）、Scene End Point <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.2361em;vertical-align:-0.3948em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-2.4413em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3948em;"><span></span></span></span></span></span></span></span></span></span>（递归终止点）。对第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.854em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0572em;">j</span></span></span></span> 个场景：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.2578em;vertical-align:-0.3831em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8747em;"><span style="top:-2.453em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3831em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:3em;vertical-align:-1.25em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;"><span class="delimsizing size4">{</span></span><span class="mord"><span class="mtable"><span class="col-align-l"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.69em;"><span style="top:-3.69em;"><span class="pstrut" style="height:3.008em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.888em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mopen mtight">(</span><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span><span class="mclose mtight">)</span></span></span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mclose">)</span><span class="mpunct">,</span></span></span><span style="top:-2.25em;"><span class="pstrut" style="height:3.008em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8648em;"><span style="top:-2.4231em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span><span style="top:-3.1031em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">−</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.413em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.888em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mopen mtight">(</span><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span><span class="mclose mtight">)</span></span></span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mclose">)</span><span class="mpunct">,</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.19em;"><span></span></span></span></span></span><span class="arraycolsep" style="width:1em;"></span><span class="col-align-l"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.69em;"><span style="top:-3.69em;"><span class="pstrut" style="height:3.008em;"></span><span class="mord"><span class="mord mathnormal">i</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord">1</span></span></span><span style="top:-2.25em;"><span class="pstrut" style="height:3.008em;"></span><span class="mord"><span class="mord">2</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≤</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord mathnormal">i</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≤</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.19em;"><span></span></span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p>递归在 agent 自行预测出 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.2361em;vertical-align:-0.3948em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-2.4413em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3948em;"><span></span></span></span></span></span></span></span></span></span> 时停止。这里没有额外的训练目标，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span></span></span></span> 就是带 CoT 的 LLM 调用；起作用的是<strong>条件集合里多了 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.2778em;vertical-align:-0.413em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8648em;"><span style="top:-2.4231em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span><span style="top:-3.1031em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">−</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.413em;"><span></span></span></span></span></span></span></span></span></span></strong> 这一项。可以理解为把镜头序列的生成从条件独立采样改成了一阶马尔可夫链式采样。</p><p><strong>镜头语言注入（CLI）</strong> 是一个有监督的序列到序列微调。数据构造分两步：先用 GPT-4o 从原始视频得到只描述物体与动作、不含镜头意图的普通描述 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>；再把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 与 ShotBench 提供的镜头级标注 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">d</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>（景别、角度、构图、运镜、布光）一起交给 GPT-4o，合成带专业镜头语言的目标描述：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">LL</span><span class="mord mathnormal mtight" style="margin-right:0.109em;">M</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">d</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span></span></p><p>微调目标是标准的条件对数似然：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">cine</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:3.106em;vertical-align:-1.2777em;"></span><span class="mord">−</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8283em;"><span style="top:-1.8723em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2777em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6828em;"><span style="top:-2.786em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span></span></p><p>注意 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">d</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 只出现在数据构造阶段，不出现在训练输入里。也就是说，模型被要求在<strong>看不到镜头标注</strong>的情况下，把&quot;物体与动作&quot;直接映射到&quot;镜头语言&quot;，这本质上是在学一个从内容到摄影决策的先验。这个设计是有代价的：它学到的是 ShotBench 语料里内容与镜头搭配的统计规律，而不是当前故事的导演意图，§9 会回到这一点。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>评测设置</strong>。数据用 MoviePrompts（来自 MovieAgent，含十部专业电影的情节描述与角色档案），另外自建 8 条同格式样本测泛化。自动指标为 CLIP-T 加 VBench 五项。为了衡量传统指标覆盖不到的叙事连贯与电影感，作者另设一套 VLM 自动评测：每条视频均匀采 8–12 关键帧，连同文本描述交给 VLM，按 1–5 分打 Script Consistency / Camera-Movement Consistency / Video Quality / Real-Movie Similarity 四项，并同时用 <strong>GPT-4o、Qwen3、Gemini-3 三个评委</strong>以缓解单模型偏置。</p><p><strong>结论一：传统指标会奖励&quot;什么都不动&quot;。</strong> 表 I 里 VGoT 的背景一致性 97.93 全场最高，而它的 Dynamic Degree 只有 16.67，同样是全场最低。论文自己点破了这一点：高一致性来自它倾向于生成近乎静止的视频。Camera Artist 在 Dyn. 80.00 的同时保持 Bg. 96.26、Subj. 79.54、Motion 99.32、Aesth. 69.51、CLIP-T 29.61。<strong>这条观察本身比方法更值得记住：一致性类指标必须与动态程度联合读，否则一个静止画面的 baseline 就能刷榜。</strong>（正文写作&quot;VGoT reports the highest subject consistency&quot;，但表 I 里主体一致性最高的是 Ours 的 79.54，VGoT 是 78.58 的次高；最高的是它的背景一致性。这处正文与表格的口径不一致，按表格为准。）</p><p><strong>结论二：镜头语言维度上基线几乎全军覆没。</strong> 表 II 三评委均值：Camera Artist 的 Script/Cam./Qual./Real. 为 3.90 / 3.55 / 4.71 / 4.02；VGoT 为 2.83 / 1.33 / 4.06 / 3.50；Anim-Director 为 2.98 / 2.30 / 3.06 / 1.61；MovieAgent 为 2.19 / 2.03 / 4.13 / 3.13。差距最大的一项是 Camera-Movement Consistency。</p><p><strong>结论三：两个模块各自负责一件事。</strong> 表 III 的消融很干净：去掉 RSG，Script Consistency 掉到 3.55（三档中最低），主体一致性从 79.54 掉到 74.69；去掉 CLI，Camera-Movement Consistency 从 <strong>3.55 掉到 2.83</strong>，Dyn. 从 80.00 掉到 74.25，视频变回静态的、纯描述性的画面。两个模块的影响落在了各自预期的指标上，没有互相串扰。</p><p><strong>人评</strong>。五点 Likert，四个维度与 VLM 评测一致，方法名隐藏、顺序随机化。Camera Artist 在所有维度上最高，Script Consistency 4.28、Real-Movie Similarity 4.12。论文没有给出参与人数，也没有报告人评与 VLM 评分之间的一致性系数。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：多智能体电影生成的瓶颈在镜头描述这一层，因为视频模型只能拍出描述里写了的东西。现有系统直接从场景生成镜头描述，既不看前一个镜头（叙事断裂），也不懂专业镜头词汇（画面平庸）。Camera Artist 用递归分镜生成把镜头序列变成一阶条件链，用一个在 ShotBench 580 对样本上 LoRA 微调的 Qwen3-4B 把普通描述翻译成带景别、机位、运镜、布光的描述。消融显示两者分工明确：去掉递归主要伤 Script Consistency，去掉注入主要伤 Camera-Movement Consistency（3.55 → 2.83）。论文顺带给出一条重要的评测教训：VGoT 靠近乎静止的视频拿到最高背景一致性（Dyn. 仅 16.67），一致性类指标必须和动态程度一起读。</p><p><strong>3 句话版</strong>：把&quot;怎么拍&quot;从隐含在 prompt 里提升为一个专职 agent 显式规划的对象。递归让镜头能看见上一个镜头，LoRA 微调让镜头描述带上专业摄影词汇。两者在四个 VLM 评委和人评上都带来一致的提升，但整套评估的可信度依赖未经校准的 VLM 判分。</p><p><strong>1 句话版</strong>：视频模型拍不出你没写的东西，所以先把分镜写成电影。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最致命的假设是：<strong>CLI 学到的&quot;内容 → 镜头语言&quot;映射，能替代导演对当前故事的意图。</strong></p><p>CLI 的训练输入只有 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>（物体与动作），镜头标注 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">d</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 只用于构造标签。这意味着模型在推理时只能根据画面内容猜该用什么镜头，学到的是 ShotBench 语料里的统计搭配。而真实的摄影决策依赖当前叙事状态：同一个&quot;人物走进房间&quot;，是紧张的推近还是舒缓的固定机位，取决于前面发生了什么、导演想让观众感受什么。论文的 RSG 确实把前一个镜头喂给了 Cinematography Shot Agent，但 CLI 这一步是在 RSG 之后作用于单条描述的，它拿不到叙事上下文。</p><p>如果这个假设不成立，后果是镜头语言变成一种<strong>与内容相关但与情绪无关的装饰</strong>：视频会显得&quot;有运镜&quot;，但运镜的时机是错的。而现有的评测恰好抓不到这一点——Camera-Movement Consistency 问的是&quot;运镜是否符合镜头描述&quot;，而镜头描述正是 CLI 自己写的，这条指标在测自洽性而非正确性。</p><p>论文为这个假设提供的证据是：Real-Movie Similarity 从基线的 1.61–3.50 提升到 4.02，人评 4.12。这是间接证据，且同样由未校准的评委给出。论文缺少的证据是：把 CLI 产出的镜头选择与专业分镜师在同一情节上的选择做比较。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>目标是验证 CLI 的收益来自&quot;微调学到了摄影先验&quot;，而不是&quot;prompt 里多了一堆摄影词汇&quot;。</p><ul><li>复用论文的公开组件：ShotBench 作为数据源，任意开源 LLM（7B 量级即可）作为改写器，任意多参考 I2V 模型（MAGREF 或同类）作为渲染器。</li><li>构造三组镜头描述，共用同一批 RSG 产出的原始描述（20 条即可）：(a) 原始描述；(b) 用未微调的同一个 LLM，在 prompt 里给定景别/机位/运镜的候选词表，要求它加上镜头语言；(c) 按论文方式 LoRA 微调后的模型改写。</li><li>各渲染成视频，测三件事：VBench 的 Dynamic Degree、光流幅度的时间曲线是否呈现出与描述中运镜类型一致的模式（例如 pull-back 应当对应单调的尺度变化）、以及一个第三方 VLM 对&quot;运镜是否被真正执行&quot;的判分。</li><li><strong>支持论文</strong>：(c) 在&quot;运镜被真正执行&quot;上显著高于 (b)，说明微调带来的不只是词汇。<strong>反驳论文</strong>：(b) 与 (c) 在所有指标上都接近，说明 580 对样本的 LoRA 只是让模型稳定地吐出摄影词表，一段精心写的 prompt 就能替代。</li></ul><p>第二步用的是同一个 LLM，因此这个对比不需要训练即可先跑通 (a) 与 (b)，一周内可完成。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>论文把提升归因给&quot;叙事连贯 + 镜头语言&quot;。一个能同样解释全部数字的替代假设是：<strong>Camera Artist 的镜头描述更长、更具体，而更长更具体的 prompt 本身就会让 MAGREF 产出动态更强、构图更稳定的画面。</strong> 也就是说，收益可能来自 prompt 的信息量，与&quot;电影性&quot;无关。</p><p>设计这样的反例：保持 Camera Artist 的完整流程，但把 CLI 微调模型换成一个<strong>注入随机镜头语言</strong>的版本——从 ShotBench 的标注词表里随机抽景别、角度、运镜、布光，拼到原始描述后面，使 prompt 长度与词汇分布与 CLI 输出统计上匹配，但与画面内容无关。如果 VBench 的 Dyn./Aesth. 和 VLM 的 Camera-Movement Consistency 仍然接近完整模型，那么这些指标测的就是 prompt 的形式而不是摄影决策的正确性，论文的核心 claim 失去支撑。真正能区分开的应该只有 Real-Movie Similarity 与人评。</p><p>另一条独立的攻击针对评测本身：<strong>Qwen3 既是所有 agent 的 backbone（30B 版），又是三个 VLM 评委之一。</strong> 在表 II 里，Qwen3 给三个基线的 Camera-Movement Consistency 分别打了 1.00、1.00、1.00，给 Camera Artist 打 3.90——这是三个评委中差距最悬殊的一组，也是唯一一组出现&quot;三个基线全部触底同分&quot;的。同族模型互评是已知的偏置来源。把 Qwen3 从评委里剔除后重算表 II 的均值，是一个成本极低但可能显著改变结论的检验；论文没有做。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：CLI 在单条镜头描述上工作，摄影决策因此与叙事状态解耦；而评测里&quot;运镜一致性&quot;测的是视频对自己写的描述的服从度，形成闭环，无法判断摄影决策本身的好坏。</p><p><strong>新 framing</strong>：把镜头语言从&quot;文本改写任务&quot;重新表述为<strong>在叙事状态上的序贯决策</strong>。定义一个显式的叙事状态（当前张力、视点归属、空间关系、上一个镜头的景别与运镜方向），摄影决策是在这个状态上选动作（景别、机位、运镜），而 reward 来自真实影片——把职业剪辑的镜头序列当作专家轨迹。这样镜头选择就有了外部的、非自证的评价标准。</p><p><strong>可借鉴的相邻工具</strong>：模仿学习里的行为克隆与 DAgger，用于从影片的镜头序列学策略；以及音乐生成中处理长程结构的做法（把段落功能作为离散控制变量），用于表达&quot;这是一个建置镜头 / 这是一个情绪高点&quot;。ShotBench 已经提供了镜头级标注，把它按影片重新组织成序列就能得到专家轨迹，不需要新采数据。</p><p><strong>第一个实验</strong>：不生成视频，只做镜头序列预测。在若干部影片的镜头标注序列上训练一个策略，给定前 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 个镜头的属性与情节摘要，预测下一个镜头的景别与运镜。评价指标是与真实影片的匹配率，并与两个 baseline 比较：预测最高频类别的 majority baseline，以及本文的 CLI 模型（把它的输出解析成属性）。如果 CLI 的匹配率接近 majority baseline，就直接证明了 §9 的怀疑——它学到的是边缘分布而非条件决策。这个实验完全在文本域进行，不烧 GPU，却能一次性检验本文最脆弱的环节。</p>',61)])])}const u=a(e,[["render",l]]);export{o as __pageData,u as default};
